        {
            DeviceId = "invoice-multiple-version-stock-replacement-test",
            Invoices =
            [
                CreateVersionedInvoiceStockDto(
                    fixture,
                    secondInvoiceId,
                    versionNumber: 2,
                    previousVersionId: fixture.FirstInvoiceId,
                    quantity: 3m),
