            .Where(entry => entry.ItemId == fixture.ItemId)
            .ToListAsync());
        Assert.Equal(thirdInvoiceId, ledgerEntry.SourceDocumentId);
        Assert.Equal(-4m, ledgerEntry.QuantityDelta);
    }

