        var unchanged = await _dbContext.Customers.IgnoreQueryFilters().AsNoTracking().SingleAsync(row => row.Id == secondId);
        Assert.Equal("LEGACY-SECOND-CUSTOMER", unchanged.NameOriginal);
    }

