    [Fact]
    public async Task Push_RejectsNewItem_WhenLegacyDescriptorGroupIsAmbiguous()
    {
        var updatedAtUtc = new DateTime(2026, 7, 29, 0, 0, 0, DateTimeKind.Utc);
