    [Fact]
    public async Task RentalBillingRunTombstone_MalformedProfileAllowsFinanceDeleteWithoutRewritingJsonOrSummary()
    {
        const string malformedRunsJson = "[ { \"RunId\": ";
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
