        var incomingAssetId = Guid.NewGuid();
        var runId = Guid.NewGuid();
        const string profileKey = "USENET|1234567890|중복프로필거래처|개별|후불|25|1|전자세금계산서";
        var existingTemplateJson = JsonSerializer.Serialize(new[]
        {
            new
            {
                ItemId = itemId,
                DisplayItemName = "IMC2010",
                BillingLineMode = "개별",
                Quantity = 1m,
                UnitPrice = 55_000m,
                Amount = 55_000m,
                IncludedAssetIds = new[] { existingAssetId }
            }
        });
        var incomingTemplateJson = JsonSerializer.Serialize(new[]
        {
            new
            {
                ItemId = itemId,
                DisplayItemName = "IMC2010",
                BillingLineMode = "개별",
                Quantity = 1m,
                UnitPrice = 55_000m,
                Amount = 55_000m,
                IncludedAssetIds = new[] { incomingAssetId }
            }
        });
        var existingRunsJson = JsonSerializer.Serialize(new[]
        {
            new SyncRentalBillingRunSnapshot
            {
                RunId = runId,
                RunKey = "2026-06",
                ScheduledDate = new DateOnly(2026, 6, 25),
                PeriodStartDate = new DateOnly(2026, 6, 1),
                PeriodEndDate = new DateOnly(2026, 6, 30),
                PeriodLabel = "2026-06",
                Status = "완료",
                BilledAmount = 55_000m,
                SettledAmount = 20_000m,
                SettlementStatus = "부분입금",
                SettledDate = new DateOnly(2026, 6, 26)
            }
        });

        var existing = new RentalBillingProfile
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Usenet,
            ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
            ProfileKey = profileKey,
            CustomerName = "중복프로필거래처",
            BusinessNumber = "123-45-67890",
            ItemName = "IMC2010",
            BillingType = "개별",
            BillingAdvanceMode = "후불",
            ManagementCompanyCode = OfficeCodeCatalog.Usenet,
            BillingMethod = "전자세금계산서",
            BillingDay = 25,
            BillingCycleMonths = 1,
            MonthlyAmount = 55_000m,
            LastBilledDate = new DateOnly(2026, 6, 25),
            LastSettledDate = new DateOnly(2026, 6, 26),
            SettledAmount = 20_000m,
            OutstandingAmount = 35_000m,
            SettlementStatus = "부분입금",
            CompletionStatus = "미완료",
            BillingStatus = "청구완료",
            BillingTemplateJson = existingTemplateJson,
            BillingRunsJson = existingRunsJson
        };
        RentalAsset CreateReferenceOnlyAsset(Guid assetId, string suffix)
            => new()
            {
                Id = assetId,
                TenantCode = TenantScopeCatalog.UsenetGroup,
                OfficeCode = OfficeCodeCatalog.Usenet,
                ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
                ManagementCompanyCode = OfficeCodeCatalog.Usenet,
                CustomerName = "Duplicate merge customer",
                CurrentCustomerName = "Duplicate merge customer",
                InstallLocation = "Duplicate merge site",
                InstallSiteName = "Duplicate merge site",
                ItemName = "IMC2010",
                ManagementId = $"DUPLICATE-MERGE-{suffix}-{assetId:N}",
                ManagementNumber = $"DUPLICATE-MERGE-{suffix}-{assetId:N}",
                AssetKey = $"DUPLICATE-MERGE-{suffix}-{assetId:N}"
            };

        _dbContext.AddRange(
            existing,
            CreateReferenceOnlyAsset(existingAssetId, "EXISTING"),
            CreateReferenceOnlyAsset(incomingAssetId, "INCOMING"));
        await _dbContext.SaveChangesAsync();
        _dbContext.ChangeTracker.Clear();

        var storedBefore = await _dbContext.RentalBillingProfiles.IgnoreQueryFilters()
            .AsNoTracking()
            .SingleAsync(profile => profile.Id == existing.Id);

        var response = await _controller.Push(new SyncPushRequest
        {
            DeviceId = "device-rental-profile-duplicate-template-merge",
            RentalBillingProfiles =
            [
                new RentalBillingProfileDto
                {
                    Id = Guid.NewGuid(),
                    TenantCode = TenantScopeCatalog.UsenetGroup,
                    OfficeCode = OfficeCodeCatalog.Usenet,
                    ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
                    ProfileKey = profileKey,
                    CustomerName = "중복프로필거래처",
                    BusinessNumber = "123-45-67890",
                    ItemName = "IMC2010",
                    BillingType = "개별",
                    BillingAdvanceMode = "후불",
                    ManagementCompanyCode = OfficeCodeCatalog.Usenet,
                    BillingMethod = "전자세금계산서",
                    BillingDay = 28,
                    BillingCycleMonths = 1,
                    MonthlyAmount = 77_000m,
                    BillingTemplateJson = incomingTemplateJson,
                    BillingRunsJson = "[]",
                    CreatedAtUtc = storedBefore.CreatedAtUtc,
                    UpdatedAtUtc = storedBefore.UpdatedAtUtc.AddMinutes(5),
                    Revision = storedBefore.Revision
                }
            ]
        }, CancellationToken.None);

        var ok = Assert.IsType<OkObjectResult>(response.Result);
        var result = Assert.IsType<SyncPushResult>(ok.Value);
        Assert.True(result.ConflictCount == 0,
            string.Join(" | ", result.Conflicts.Select(conflict => $"{conflict.EntityName}:{conflict.Reason}")));

        _dbContext.ChangeTracker.Clear();
        var profiles = await _dbContext.RentalBillingProfiles.IgnoreQueryFilters()
            .AsNoTracking()
            .ToListAsync();
        var storedProfile = Assert.Single(profiles);
        Assert.Equal(existing.Id, storedProfile.Id);
        Assert.Equal(28, storedProfile.BillingDay);
        Assert.Equal(77_000m, storedProfile.MonthlyAmount);
        Assert.Equal(new DateOnly(2026, 6, 25), storedProfile.LastBilledDate);
        Assert.Equal(new DateOnly(2026, 6, 26), storedProfile.LastSettledDate);
        Assert.Equal(20_000m, storedProfile.SettledAmount);
        Assert.Equal(35_000m, storedProfile.OutstandingAmount);
        Assert.Equal("부분입금", storedProfile.SettlementStatus);
        Assert.Equal("미완료", storedProfile.CompletionStatus);
        Assert.Equal("청구완료", storedProfile.BillingStatus);

        using var templateDocument = JsonDocument.Parse(storedProfile.BillingTemplateJson);
        var includedAssetIds = templateDocument.RootElement
            .EnumerateArray()
            .SelectMany(item => item.GetProperty("IncludedAssetIds").EnumerateArray())
            .Select(value => value.GetGuid())
            .OrderBy(value => value)
            .ToArray();
        Assert.Equal(new[] { existingAssetId, incomingAssetId }.OrderBy(value => value), includedAssetIds);

        using var runsDocument = JsonDocument.Parse(storedProfile.BillingRunsJson);
        Assert.Contains(runsDocument.RootElement.EnumerateArray(), run =>
            run.GetProperty("RunId").GetGuid() == runId &&
            run.GetProperty("SettlementStatus").GetString() == "부분입금");
    }

    [Fact]
    public async Task Push_RejectsNaturalKeyRentalBillingProfileMerge_WhenRawIncomingTemplateContainsDuplicateAssetReferences()
    {
        var assetId = Guid.NewGuid();
        var profileKey = $"RAW-DUPLICATE-MERGE-{Guid.NewGuid():N}";
        var existing = new RentalBillingProfile
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Usenet,
            ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
            ManagementCompanyCode = OfficeCodeCatalog.Usenet,
            ProfileKey = profileKey,
            CustomerName = "Raw duplicate merge customer",
            ItemName = "Raw duplicate merge item",
            BillingTemplateJson = JsonSerializer.Serialize(new[]
            {
                new { IncludedAssetIds = new[] { assetId } }
            }),
            BillingDay = 25,
            MonthlyAmount = 40_000m,
            IsActive = true
        };
        _dbContext.AddRange(
            new RentalManagementCompany
            {
                Id = Guid.NewGuid(),
                TenantCode = TenantScopeCatalog.UsenetGroup,
                Code = OfficeCodeCatalog.Usenet,
                Name = OfficeCodeCatalog.GetOfficeDisplayName(OfficeCodeCatalog.Usenet),
                IsSystemDefault = true,
                IsActive = true
            },
            existing,
            new RentalAsset
            {
                Id = assetId,
                TenantCode = TenantScopeCatalog.UsenetGroup,
                OfficeCode = OfficeCodeCatalog.Usenet,
                ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
                ManagementCompanyCode = OfficeCodeCatalog.Usenet,
                CustomerName = existing.CustomerName,
                CurrentCustomerName = existing.CustomerName,
                InstallLocation = "Raw duplicate merge site",
                InstallSiteName = "Raw duplicate merge site",
                ItemName = existing.ItemName,
                ManagementId = $"RAW-DUPLICATE-MERGE-{assetId:N}",
                ManagementNumber = $"RAW-DUPLICATE-MERGE-{assetId:N}",
                AssetKey = $"RAW-DUPLICATE-MERGE-{assetId:N}"
            });
        await _dbContext.SaveChangesAsync();
        var originalRevision = existing.Revision;
        var originalUpdatedAtUtc = existing.UpdatedAtUtc;
        var mutationId = $"raw-duplicate-merge:{Guid.NewGuid():N}";

        var response = await _controller.Push(new SyncPushRequest
        {
            DeviceId = "device-raw-duplicate-rental-profile-merge",
            RentalBillingProfiles =
            [
                new RentalBillingProfileDto
                {
                    Id = Guid.NewGuid(),
                    TenantCode = existing.TenantCode,
                    OfficeCode = existing.OfficeCode,
                    ResponsibleOfficeCode = existing.ResponsibleOfficeCode,
                    ManagementCompanyCode = existing.ManagementCompanyCode,
                    ProfileKey = profileKey,
                    CustomerName = existing.CustomerName,
                    ItemName = existing.ItemName,
                    BillingTemplateJson = JsonSerializer.Serialize(new[]
                    {
                        new { IncludedAssetIds = new[] { assetId, assetId } }
                    }),
                    BillingDay = 28,
                    MonthlyAmount = 77_000m,
                    IsActive = true,
                    Revision = originalRevision,
                    ExpectedRevision = originalRevision,
                    MutationId = mutationId,
                    MutationCreatedAtUtc = originalUpdatedAtUtc.AddMinutes(1),
                    CreatedAtUtc = existing.CreatedAtUtc,
                    UpdatedAtUtc = originalUpdatedAtUtc.AddMinutes(1)
                }
            ]
        }, CancellationToken.None);

        var ok = Assert.IsType<OkObjectResult>(response.Result);
        var result = Assert.IsType<SyncPushResult>(ok.Value);
        Assert.Equal(0, result.AcceptedCount);
        Assert.Contains(result.Conflicts, conflict =>
            conflict.EntityName == nameof(RentalBillingProfile));
        Assert.False(await _dbContext.ProcessedSyncMutations.AnyAsync(mutation =>
            mutation.MutationId == mutationId));
        _dbContext.ChangeTracker.Clear();
        var unchanged = await _dbContext.RentalBillingProfiles.IgnoreQueryFilters()
            .AsNoTracking()
            .SingleAsync(profile => profile.Id == existing.Id);
        Assert.Equal(originalRevision, unchanged.Revision);
        Assert.Equal(originalUpdatedAtUtc, unchanged.UpdatedAtUtc);
        Assert.Equal(40_000m, unchanged.MonthlyAmount);
    }

    [Fact]
    public async Task Push_ReusedRentalBillingProfile_ReturnsAcceptedRevisionAliasForOriginalIncomingId_WhenBatchHasOtherConflict()
    {
        _dbContext.RentalManagementCompanies.Add(new RentalManagementCompany
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            Code = OfficeCodeCatalog.Usenet,
            Name = "유즈넷"
        });

        var existingProfile = new RentalBillingProfile
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Usenet,
            ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
            ProfileKey = "USENET|ALIAS-ACCEPTED-PROFILE|개별|후불|25|1|전자세금계산서",
            CustomerName = "accepted alias rental customer",
            BusinessNumber = "555-10-11111",
            ItemName = "IMC2010",
            BillingType = "개별",
            BillingAdvanceMode = "후불",
            ManagementCompanyCode = OfficeCodeCatalog.Usenet,
            BillingMethod = "전자세금계산서",
            BillingDay = 25,
            BillingCycleMonths = 1,
            MonthlyAmount = 55_000m
        };
        var conflictingCustomer = new Customer
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Usenet,
            ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
            NameOriginal = "accepted alias conflict customer",
            NameMatchKey = "ACCEPTEDALIASCONFLICTCUSTOMER",
            TradeType = CustomerClassificationNormalizer.Sales
        };
        _dbContext.RentalBillingProfiles.Add(existingProfile);
        _dbContext.Customers.Add(conflictingCustomer);
        await _dbContext.SaveChangesAsync();
        _dbContext.ChangeTracker.Clear();

        var storedProfile = await _dbContext.RentalBillingProfiles.IgnoreQueryFilters()
            .AsNoTracking()
            .SingleAsync(profile => profile.Id == existingProfile.Id);
        var storedCustomer = await _dbContext.Customers.IgnoreQueryFilters()
            .AsNoTracking()
            .SingleAsync(customer => customer.Id == conflictingCustomer.Id);
        var originalIncomingProfileId = Guid.NewGuid();

        var response = await _controller.Push(new SyncPushRequest
        {
            DeviceId = "device-rental-profile-accepted-alias-with-conflict",
            RentalBillingProfiles =
            [
                new RentalBillingProfileDto
                {
                    Id = originalIncomingProfileId,
                    TenantCode = TenantScopeCatalog.UsenetGroup,
                    OfficeCode = OfficeCodeCatalog.Usenet,
                    ResponsibleOfficeCode = OfficeCodeCatalog.Usenet,
                    ProfileKey = existingProfile.ProfileKey,
                    CustomerName = existingProfile.CustomerName,
                    BusinessNumber = existingProfile.BusinessNumber,
                    ItemName = existingProfile.ItemName,
                    BillingType = existingProfile.BillingType,
                    BillingAdvanceMode = existingProfile.BillingAdvanceMode,
                    ManagementCompanyCode = existingProfile.ManagementCompanyCode,
                    BillingMethod = existingProfile.BillingMethod,
                    BillingDay = 28,
                    BillingCycleMonths = 1,
                    MonthlyAmount = 77_000m,
                    Revision = storedProfile.Revision,
                    CreatedAtUtc = storedProfile.CreatedAtUtc,
                    UpdatedAtUtc = storedProfile.UpdatedAtUtc.AddMinutes(5)
                }
            ],
            Customers =
            [
                new CustomerDto
                {
                    Id = conflictingCustomer.Id,
                    TenantCode = conflictingCustomer.TenantCode,
                    OfficeCode = conflictingCustomer.OfficeCode,
                    ResponsibleOfficeCode = conflictingCustomer.ResponsibleOfficeCode,
                    NameOriginal = "accepted alias conflict customer changed",
                    NameMatchKey = "ACCEPTEDALIASCONFLICTCUSTOMERCHANGED",
                    TradeType = CustomerClassificationNormalizer.Sales,
                    Revision = storedCustomer.Revision,
                    ExpectedRevision = storedCustomer.Revision + 1,
                    CreatedAtUtc = storedCustomer.CreatedAtUtc,
                    UpdatedAtUtc = storedCustomer.UpdatedAtUtc.AddMinutes(5)
                }
            ]
        }, CancellationToken.None);

        var ok = Assert.IsType<OkObjectResult>(response.Result);
        var result = Assert.IsType<SyncPushResult>(ok.Value);
        Assert.Equal(1, result.ConflictCount);
        Assert.Contains(result.Conflicts, conflict =>
            conflict.EntityName == nameof(Customer) &&
            conflict.EntityId == conflictingCustomer.Id.ToString("D"));

        var rentalAcceptedRevisions = result.AcceptedRevisions
            .Where(revision => revision.EntityName == nameof(RentalBillingProfile))
            .ToList();
        Assert.Contains(rentalAcceptedRevisions, revision => revision.EntityId == existingProfile.Id);
        Assert.Contains(rentalAcceptedRevisions, revision => revision.EntityId == originalIncomingProfileId);

        _dbContext.ChangeTracker.Clear();
        var profiles = await _dbContext.RentalBillingProfiles.IgnoreQueryFilters()
            .AsNoTracking()
            .ToListAsync();
        var savedProfile = Assert.Single(profiles);
        Assert.Equal(existingProfile.Id, savedProfile.Id);
        Assert.Equal(28, savedProfile.BillingDay);
        Assert.Equal(77_000m, savedProfile.MonthlyAmount);
    }

