    [Fact]
    public async Task Pull_ReturnsCustomerContractMetadataWithoutFileContent()
    {
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Usenet,
