        };
        var visibleTransaction = new TransactionRecord
        {
            Id = Guid.NewGuid(),
            CustomerId = visibleCustomer.Id,
            TenantCode = TenantScopeCatalog.UsenetGroup,
            OfficeCode = OfficeCodeCatalog.Yeonsu,
            ResponsibleOfficeCode = OfficeCodeCatalog.Yeonsu,
