        await _dbContext.SaveChangesAsync();
        var purgeRevision = purgeRecord.Revision;
        var purgeUpdatedAtUtc = purgeRecord.UpdatedAtUtc;

        RentalBillingProfileDto CreatePriorIncarnation(bool deleted, string mutationId)
            => new()
