    private sealed class TestStoredFileReferenceReconciler(
        AppDbContext dbContext,
        ICentralFileStorage fileStorage) : IStoredFileReferenceReconciler
    {
        public async Task DeleteUnreferencedAsync(
            IEnumerable<string> candidatePaths,
            CancellationToken cancellationToken = default)
        {
            var candidates = candidatePaths
                .Where(path => !string.IsNullOrWhiteSpace(path))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            var referenced = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var path in await dbContext.CustomerContracts
                         .IgnoreQueryFilters()
                         .Where(current => candidates.Contains(current.StoragePath))
                         .Select(current => current.StoragePath)
                         .ToListAsync(cancellationToken))
            {
                referenced.Add(path);
            }

            foreach (var path in await dbContext.TransactionAttachments
                         .IgnoreQueryFilters()
                         .Where(current => candidates.Contains(current.StoragePath))
                         .Select(current => current.StoragePath)
                         .ToListAsync(cancellationToken))
            {
                referenced.Add(path);
            }

            foreach (var path in await dbContext.PaymentAttachments
                         .IgnoreQueryFilters()
                         .Where(current => candidates.Contains(current.StoragePath))
                         .Select(current => current.StoragePath)
                         .ToListAsync(cancellationToken))
            {
                referenced.Add(path);
            }

            foreach (var path in candidates.Where(path => !referenced.Contains(path)))
                fileStorage.DeleteIfExists(path);
        }

        public Task<PaymentAttachment?> FindPaymentAttachmentAsync(
            Guid attachmentId,
            CancellationToken cancellationToken = default)
            => Task.FromResult<PaymentAttachment?>(null);
    }

    private sealed class RecordingCentralFileStorage : ICentralFileStorage
    {
        public string RootPath => Path.GetTempPath();
        public List<(string Area, string OwnerId, Guid FileId, string FileName, byte[] Content, string StoredPath)> SaveCalls { get; } = [];
        public List<string> DeletedPaths { get; } = [];

        public Task<string> SaveBytesAsync(string area, string ownerId, Guid fileId, string fileName, byte[] content, CancellationToken cancellationToken = default)
        {
            var storedPath = Path.Combine(RootPath, area, ownerId, fileId.ToString("N"), fileName);
            SaveCalls.Add((area, ownerId, fileId, fileName, content.ToArray(), storedPath));
            return Task.FromResult(storedPath);
        }

        public byte[] ReadBytes(string? storedPath, byte[]? fallback = null)
            => fallback ?? [];

        public void DeleteIfExists(string? storedPath)
        {
            if (!string.IsNullOrWhiteSpace(storedPath))
                DeletedPaths.Add(storedPath);
        }
    }

    private sealed class CancellingAfterSaveCentralFileStorage : ICentralFileStorage
    {
        private readonly CancellationTokenSource _cancellation;

        public CancellingAfterSaveCentralFileStorage(CancellationTokenSource cancellation)
            => _cancellation = cancellation;

        public string RootPath => Path.GetTempPath();
        public List<(string Area, string OwnerId, Guid FileId, string FileName, byte[] Content, string StoredPath)> SaveCalls { get; } = [];
        public List<string> DeletedPaths { get; } = [];

        public Task<string> SaveBytesAsync(string area, string ownerId, Guid fileId, string fileName, byte[] content, CancellationToken cancellationToken = default)
        {
            var storedPath = Path.Combine(RootPath, area, ownerId, fileId.ToString("N"), fileName);
            SaveCalls.Add((area, ownerId, fileId, fileName, content.ToArray(), storedPath));
            _cancellation.Cancel();
            return Task.FromResult(storedPath);
        }

        public byte[] ReadBytes(string? storedPath, byte[]? fallback = null)
            => fallback ?? [];

        public void DeleteIfExists(string? storedPath)
        {
            if (!string.IsNullOrWhiteSpace(storedPath))
                DeletedPaths.Add(storedPath);
        }
    }

